// OST's text in Teams' app languages (Settings ▸ General ▸ Language and
// regional formats ▸ App language).
//
// The QML marks its text with qsTr(), answered by OST's one translator
// (teams_cli::i18n, also the engine's and the backend's). i18n/ids.json
// (generated by i18n/l10n.py) keys each such string to the Teams string id
// it is. The
// catalogue of Teams' own translations, built on the device from Teams'
// string resources (api::teams_strings, cached in
// ~/.cache/ost/i18n/<locale>.json), maps each id to its text in Qt's form:
// %1, %2… for Teams' placeholders, %n for a count, and a plural message as
// {"=1": …, "one": …, "other": …}.
//
// Teams applies its app language at start (after Save and restart), sets
// the document direction from it (right to left for Arabic, Hebrew,
// Persian…) and formats with that culture; OST does the same with one
// translator installed before the QML loads, Qt's layout direction and the
// default QLocale.

#include <QtCore/QCoreApplication>
#include <QtCore/QLocale>
#include <QtCore/QTranslator>
#include <QtCore/QTimer>
#include <QtCore/QUrl>
#include <QtQml/QQmlComponent>
#include <QtQml/QQmlContext>
#include <QtQml/QQmlEngine>
#include <QtQml/QQmlListReference>
#include <QtGui/QGuiApplication>
#include <QtGui/QWindow>
#include <QtQuick/QQuickItem>
#include <QtQuick/QQuickWindow>

namespace {

// The translator itself is OST's one translator in Rust (teams_cli::i18n,
// shared with the engine and the backend): ids, catalogue, Teams' plural
// rules and the language's digits. This asks it for each qsTr().
extern "C" size_t ost_i18n_lookup(const char *source, const char *disambiguation, int n, char *out, size_t cap);

class Translator : public QTranslator
{
public:
    bool isEmpty() const override { return false; }

    QString translate(const char *, const char *sourceText, const char *disambiguation, int n) const override
    {
        if (!sourceText)
            return {};
        char buf[1024];
        size_t len = ost_i18n_lookup(sourceText, disambiguation ? disambiguation : "", n, buf, sizeof buf);
        if (len == 0)
            return {};
        if (len <= sizeof buf)
            return QString::fromUtf8(buf, qsizetype(len));
        QByteArray big(qsizetype(len), Qt::Uninitialized);
        len = ost_i18n_lookup(sourceText, disambiguation ? disambiguation : "", n, big.data(), size_t(big.size()));
        return len && len <= size_t(big.size()) ? QString::fromUtf8(big.constData(), qsizetype(len)) : QString();
    }
};

// Right to left (Arabic, Hebrew, Persian), Teams' document is dir="rtl":
// its whole layout is the mirror image of the left-to-right one (every
// row, pane, margin and offset), while text and pictures read as
// themselves, each piece of text aligned to the start of its block (the
// right; English and names included), message bodies following their own
// direction (dir="auto"), and the icons its library marks flipInRtl drawn
// mirrored.
//
// OST does the same to each window: every top-level item of the window's
// content is mirrored about the window's centre line (a Scale of -1),
// and then each item that draws text, a picture, video or a web page is
// mirrored back about its own centre, so it reads normally where the
// mirrored layout puts it. Text left-aligned to its block becomes
// right-aligned (and right becomes left), unless the item sets
// `ostAutoDirection` (it follows its content). Pictures are mirrored back
// with Image.mirror, unless the item sets `ostMirrorsItself` (FluentIcon:
// it leaves Teams' flipInRtl icons mirrored). Items are found by sweeping
// the windows a few times a second; each is handled once.
class RtlLayout : public QObject
{
public:
    explicit RtlLayout(QObject *parent) : QObject(parent)
    {
        m_timer.setInterval(150);
        connect(&m_timer, &QTimer::timeout, this, &RtlLayout::sweep);
        m_timer.start();
    }

private:
    enum Kind { Other, Text, TextInput, TextEdit, Image, Opaque };

    void sweep()
    {
        for (QWindow *w : QGuiApplication::topLevelWindows()) {
            auto *qw = qobject_cast<QQuickWindow *>(w);
            if (!qw || !qw->isVisible())
                continue;
            QQuickItem *root = qw->contentItem();
            QQmlEngine *engine = nullptr;
            for (QQuickItem *c : root->childItems()) {
                if (!engine)
                    engine = qmlEngine(c);
            }
            if (!engine)
                continue;
            for (QQuickItem *c : root->childItems()) {
                if (c->property("_ostRtl").isNull()) {
                    c->setProperty("_ostRtl", true);
                    addScale(engine, c, root);
                }
                visit(engine, c);
            }
        }
    }

    void visit(QQmlEngine *engine, QQuickItem *item)
    {
        for (QQuickItem *c : item->childItems()) {
            const Kind k = kindOf(c->metaObject());
            if (c->property("_ostRtl").isNull()) {
                c->setProperty("_ostRtl", true);
                handle(engine, c, k);
            }
            if (k == Other || k == Image)
                visit(engine, c);
        }
    }

    void handle(QQmlEngine *engine, QQuickItem *c, Kind k)
    {
        const QVariant autoDir = c->property("ostAutoDirection");
        const bool followsContent = autoDir.isValid() && autoDir.toBool();
        switch (k) {
        case Text:
        case TextInput:
            if (!followsContent) {
                const int a = c->property("horizontalAlignment").toInt();
                const QString text = c->property("text").toString();
                if (a == Qt::AlignLeft)
                    c->setProperty("horizontalAlignment", int(Qt::AlignRight));
                else if (a == Qt::AlignRight && (text.isEmpty() || !text.isRightToLeft()))
                    c->setProperty("horizontalAlignment", int(Qt::AlignLeft));
            }
            addScale(engine, c, nullptr);
            break;
        case TextEdit:
        case Opaque:
            addScale(engine, c, nullptr);
            break;
        case Image: {
            const QVariant own = c->property("ostMirrorsItself");
            if (!(own.isValid() && own.toBool()))
                c->setProperty("mirror", !c->property("mirror").toBool());
            break;
        }
        case Other:
            break;
        }
    }

    // A Scale of -1 about `about`'s centre line (the window's) or the
    // item's own.
    void addScale(QQmlEngine *engine, QQuickItem *item, QQuickItem *about)
    {
        if (!m_scale || m_scale->engine() != engine) {
            delete m_scale;
            m_scale = new QQmlComponent(engine, this);
            m_scale->setData("import QtQuick\n"
                             "Scale { property Item t; property Item w; xScale: -1\n"
                             "  // the item's drawn centre: after its own scale about its transformOrigin\n"
                             "  readonly property real cx: !t ? 0 : t.width / 2 + (t.scale - 1) * ([Item.TopLeft, Item.Left, Item.BottomLeft].indexOf(t.transformOrigin) >= 0 ? t.width / 2 : [Item.TopRight, Item.Right, Item.BottomRight].indexOf(t.transformOrigin) >= 0 ? -t.width / 2 : 0)\n"
                             "  origin.x: !t ? 0 : w ? w.width / 2 - t.x : cx }\n",
                             QUrl());
        }
        QObject *s = m_scale->beginCreate(engine->rootContext());
        if (!s)
            return;
        s->setProperty("t", QVariant::fromValue(item));
        s->setProperty("w", QVariant::fromValue(about));
        m_scale->completeCreate();
        s->setParent(item);
        QQmlListReference(item, "transform").append(s);
    }

    // Qt Quick's item classes are private: known by name.
    static Kind kindOf(const QMetaObject *mo)
    {
        for (; mo; mo = mo->superClass()) {
            const char *n = mo->className();
            if (qstrcmp(n, "QQuickText") == 0)
                return Text;
            if (qstrcmp(n, "QQuickTextInput") == 0)
                return TextInput;
            if (qstrcmp(n, "QQuickTextEdit") == 0)
                return TextEdit;
            if (qstrcmp(n, "QQuickImage") == 0)
                return Image;
            if (qstrcmp(n, "QQuickPaintedItem") == 0 || qstrcmp(n, "QQuickCanvasItem") == 0 || qstrcmp(n, "QQuickVideoOutput") == 0
                || qstrcmp(n, "QQuickWebEngineView") == 0)
                return Opaque;
            if (qstrcmp(n, "QQuickItem") == 0)
                return Other;
        }
        return Other;
    }

    QTimer m_timer;
    QQmlComponent *m_scale = nullptr;
};

} // namespace

// Install OST's text (teams_cli::i18n, installed first), the app
// language's layout direction and its culture; before the QML loads.
extern "C" void ost_install_translator(const char *culture, bool rtl)
{
    QLocale::setDefault(QLocale(QString::fromUtf8(culture)));
    QGuiApplication::setLayoutDirection(rtl ? Qt::RightToLeft : Qt::LeftToRight);
    if (rtl)
        new RtlLayout(QCoreApplication::instance());
    auto *t = new Translator;
    t->setParent(QCoreApplication::instance());
    QCoreApplication::installTranslator(t);
}
